package net.civeira.phylax.features.document.themeasset.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.ThemeAssetBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class ThemeAssetBatchController implements ThemeAssetBatchApi {

  /**
   * ThemeAsset
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeAssetDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeAssetDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeAssetEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param code
   * @param theme
   * @param themes
   * @return
   */
  @Override
  public Response themeAssetApiBatchDelete(final List<String> uids, final String search,
      final String code, final String theme, final List<String> themes) {
    return deleteController.themeAssetApiBatchDelete(uids, search, code, theme, themes);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeAssetApiBatchDeleteQuery(final String batchId) {
    return deleteController.themeAssetApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param code
   * @param theme
   * @param themes
   * @return
   */
  @Override
  public Response themeAssetApiBatchDisable(final List<String> uids, final String search,
      final String code, final String theme, final List<String> themes) {
    return disableController.themeAssetApiBatchDisable(uids, search, code, theme, themes);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeAssetApiBatchDisableQuery(final String batchId) {
    return disableController.themeAssetApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param code
   * @param theme
   * @param themes
   * @return
   */
  @Override
  public Response themeAssetApiBatchEnable(final List<String> uids, final String search,
      final String code, final String theme, final List<String> themes) {
    return enableController.themeAssetApiBatchEnable(uids, search, code, theme, themes);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeAssetApiBatchEnableQuery(final String batchId) {
    return enableController.themeAssetApiBatchEnableQuery(batchId);
  }
}
